/* \u062F\u06A9\u0645\u0647\u0654 \xAB\u0641\u0631\u0648\u0634 \u06CC\u06A9\u067E\u0627\u0631\u0686\u0647\xBB (\u0628\u0646\u0641\u0634) \u0647\u0645\u200C\u0631\u0646\u06AF \u062A\u0645 */
